using System.Data;
using LittleSteps.Api.Data;
using LittleSteps.Api.Domain;
using LittleSteps.Api.Mapping;
using LittleSteps.Api.ViewModels;
using Microsoft.EntityFrameworkCore;
using E = LittleSteps.Api.Data.Entities;
namespace LittleSteps.Api.Services;
public interface IGateService { Task<object> Visits(DateOnly? date); Task<object> RegisterVisit(VisitRequest request, E.Staff actor); Task CheckOut(int id, E.Staff actor); Task<object> Check(ExitCheckRequest request, E.Staff actor); Task<object> Confirm(ExitRequest request, E.Staff actor); Task<object> Exits(DateOnly? date); }
public sealed class GateService(AppDbContext db, IAuditService audit, SchoolClock clock) : IGateService
{
    public async Task<object> Visits(DateOnly? date) { var (start, end) = clock.Day(date ?? clock.Today); return new { onSite = await db.Visits.CountAsync(v => v.TimeOut == null), items = await db.Visits.Where(v => v.TimeIn >= start && v.TimeIn < end || v.TimeOut == null).OrderByDescending(v => v.TimeIn).Select(v => new { id = v.VisitId, fullName = v.VisitorName, emiratesId = v.VisitorEmiratesId, v.Reason, v.PersonVisited, v.TimeIn, v.TimeOut }).ToListAsync() }; }
    public async Task<object> RegisterVisit(VisitRequest r, E.Staff actor) { var d = new Visit(r.FullName, r.EmiratesId, r.Reason, r.PersonVisited, clock.Now); var v = new E.Visit { VisitorName = d.VisitorName, VisitorEmiratesId = d.VisitorEmiratesId.Value, Reason = d.Reason, PersonVisited = d.PersonVisited, TimeIn = d.TimeIn, RegisteredByStaffId = actor.StaffId }; db.Visits.Add(v); audit.Record("Gate control", "Visitor in", d.VisitorName + " · " + d.Reason, staff: actor); await db.SaveChangesAsync(); return new { id = v.VisitId, v.TimeIn }; }
    public async Task CheckOut(int id, E.Staff actor) { await using var tx = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable); var v = await db.Visits.SingleOrDefaultAsync(v => v.VisitId == id) ?? throw new DomainException("Visit not found.", 404); var d = new Visit(v.VisitorName, v.VisitorEmiratesId, v.Reason, v.PersonVisited, v.TimeIn, v.TimeOut); d.CheckOut(clock.Now); v.TimeOut = d.TimeOut; audit.Record("Gate control", "Visitor out", v.VisitorName, staff: actor); await db.SaveChangesAsync(); await tx.CommitAsync(); }
    private async Task<EarlyExitRequest> Request(int id, string emiratesId) { var eid = new EmiratesId(emiratesId); var s = await db.Students.Include(s => s.StudentGuardians).ThenInclude(l => l.Guardian).SingleOrDefaultAsync(s => s.StudentId == id && s.IsActive) ?? throw new DomainException("Student not found.", 404); var match = s.StudentGuardians.SingleOrDefault(l => l.Guardian.EmiratesId == eid.Value); return new EarlyExitRequest(StudentMapper.FromEntity(s), eid, match is null ? null : StudentMapper.Guardian(match.Guardian)); }
    private void Store(EarlyExitRequest d, E.Staff actor) { db.EarlyExits.Add(new E.EarlyExit { StudentId = d.Student.Id, PresentedEmiratesId = d.PresentedId.Value, GuardianId = d.Guardian?.Id, Authorized = d.Authorized, Reason = d.Reason, OccurredAt = clock.Now, GuardStaffId = actor.StaffId }); audit.Record("Gate control", "Early exit", d.Student.FullName + (d.Authorized ? " with " + d.Guardian!.FullName : ": Emirates ID not linked"), d.Authorized ? "OK" : "Refused", actor); }
    public async Task<object> Check(ExitCheckRequest r, E.Staff actor) { var d = await Request(r.StudentId, r.EmiratesId); if (!d.Check()) { d.Refuse(); Store(d, actor); await db.SaveChangesAsync(); return new { authorized = false, message = "Exit refused: this Emirates ID is not a registered responsible adult." }; } var relation = await db.StudentGuardians.SingleAsync(l => l.StudentId == r.StudentId && l.GuardianId == d.Guardian!.Id); return new { authorized = true, guardian = new { id = d.Guardian!.Id, d.Guardian.FullName, relation.Relationship, photoUrl = d.Guardian.Photo is null ? null : $"/guardians/{d.Guardian.Id}/photo" } }; }
    public async Task<object> Confirm(ExitRequest r, E.Staff actor) { await using var tx = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable); var d = await Request(r.StudentId, r.EmiratesId); if (!d.Check()) { d.Refuse(); Store(d, actor); await db.SaveChangesAsync(); await tx.CommitAsync(); throw new DomainException("Exit refused: this adult is no longer linked to the child.", 403); } var (start, end) = clock.Day(clock.Today); if (await db.EarlyExits.AnyAsync(e => e.StudentId == r.StudentId && e.Authorized && e.OccurredAt >= start && e.OccurredAt < end)) throw new DomainException("This student has already left early today.", 409); if (!await db.AttendanceRecords.AnyAsync(a => a.StudentId == r.StudentId && a.AttendanceDate == clock.Today && a.Status == 'P')) throw new DomainException("The child must be marked Present today before an early exit can be confirmed.", 409); d.Authorize(r.Reason); Store(d, actor); await db.SaveChangesAsync(); await tx.CommitAsync(); return new { authorized = true, occurredAt = clock.Now }; }
    public async Task<object> Exits(DateOnly? date) { var (start, end) = clock.Day(date ?? clock.Today); var rows = await db.EarlyExits.Include(e => e.Student).ThenInclude(s => s.Class).Include(e => e.Guardian).Where(e => e.OccurredAt >= start && e.OccurredAt < end).OrderByDescending(e => e.OccurredAt).ToListAsync(); return rows.Select(e => new { id = e.EarlyExitId, student = StudentService.Summary(e.Student), e.Authorized, guardianName = e.Guardian?.FullName, e.Reason, e.OccurredAt }); }
}
